/// <summary>
/// Which customer provider to exchange an identity token with, and how. These values come from
/// the application's own configuration, never from the platform.
/// </summary>
public record FfiFederationSpec {
    
    /// <summary>
    /// AWS STS `AssumeRoleWithWebIdentity`, scoped to the one key.
    /// </summary>
    public record Aws (
        string @roleArn,
        string @sessionName,
        string @region,
        string @keyArn,
        uint @durationSecs
    ) : FfiFederationSpec {}
    
    /// <summary>
    /// GCP workload identity federation.
    /// </summary>
    public record Gcp (
        string @audience
    ) : FfiFederationSpec {}
    
    /// <summary>
    /// Microsoft Entra workload identity federation.
    /// </summary>
    public record Azure (
        string @tenantId,
        string @clientId,
        string @scope
    ) : FfiFederationSpec {}
    
    /// <summary>
    /// Vault JWT login.
    /// </summary>
    public record Vault (
        string @vaultAddr,
        string @mount,
        string @role
    ) : FfiFederationSpec {}
    

    
}

class FfiConverterTypeFfiFederationSpec : FfiConverterRustBuffer<FfiFederationSpec>{
    public static FfiConverterRustBuffer<FfiFederationSpec> INSTANCE = new FfiConverterTypeFfiFederationSpec();

    public override FfiFederationSpec Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new FfiFederationSpec.Aws(
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterUInt32.INSTANCE.Read(stream)
                );
            case 2:
                return new FfiFederationSpec.Gcp(
                    FfiConverterString.INSTANCE.Read(stream)
                );
            case 3:
                return new FfiFederationSpec.Azure(
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterString.INSTANCE.Read(stream)
                );
            case 4:
                return new FfiFederationSpec.Vault(
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterString.INSTANCE.Read(stream)
                );
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeFfiFederationSpec.Read()", value));
        }
    }

    public override int AllocationSize(FfiFederationSpec value) {
        switch (value) {
            case FfiFederationSpec.Aws variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@roleArn)
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@sessionName)
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@region)
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@keyArn)
                    + FfiConverterUInt32.INSTANCE.AllocationSize(variant_value.@durationSecs);
            case FfiFederationSpec.Gcp variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@audience);
            case FfiFederationSpec.Azure variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@tenantId)
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@clientId)
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@scope);
            case FfiFederationSpec.Vault variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@vaultAddr)
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@mount)
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@role);
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeFfiFederationSpec.AllocationSize()", value));
        }
    }

    public override void Write(FfiFederationSpec value, BigEndianStream stream) {
        switch (value) {
            case FfiFederationSpec.Aws variant_value:
                stream.WriteInt(1);
                FfiConverterString.INSTANCE.Write(variant_value.@roleArn, stream);
                FfiConverterString.INSTANCE.Write(variant_value.@sessionName, stream);
                FfiConverterString.INSTANCE.Write(variant_value.@region, stream);
                FfiConverterString.INSTANCE.Write(variant_value.@keyArn, stream);
                FfiConverterUInt32.INSTANCE.Write(variant_value.@durationSecs, stream);
                break;
            case FfiFederationSpec.Gcp variant_value:
                stream.WriteInt(2);
                FfiConverterString.INSTANCE.Write(variant_value.@audience, stream);
                break;
            case FfiFederationSpec.Azure variant_value:
                stream.WriteInt(3);
                FfiConverterString.INSTANCE.Write(variant_value.@tenantId, stream);
                FfiConverterString.INSTANCE.Write(variant_value.@clientId, stream);
                FfiConverterString.INSTANCE.Write(variant_value.@scope, stream);
                break;
            case FfiFederationSpec.Vault variant_value:
                stream.WriteInt(4);
                FfiConverterString.INSTANCE.Write(variant_value.@vaultAddr, stream);
                FfiConverterString.INSTANCE.Write(variant_value.@mount, stream);
                FfiConverterString.INSTANCE.Write(variant_value.@role, stream);
                break;
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeFfiFederationSpec.Write()", value));
        }
    }
}







