/// <summary>
/// uniffi-facing error type for `zk_encrypt` / `zk_decrypt` native exports.
///
/// `ZkFfiError` is a struct and cannot directly implement `uniffi::Error`
/// (which requires an enum). This enum flattens the struct into three
/// variants — platform error, upstream KMS error, and posture floor
/// violation — that uniffi-generated Swift/Kotlin/Python code can pattern-match.
/// Converted from `ZkFfiError` at the `ffi_uniffi` boundary.
/// </summary>
public class ZkFfiUniffiException: UniffiException {
    ZkFfiUniffiException() : base() {}
    ZkFfiUniffiException(String @Message) : base(@Message) {}

    // Each variant is a nested class
    
    /// <summary>
    /// A platform error with a `K9O_*` wire code.
    /// </summary>
    
    public class Platform : ZkFfiUniffiException {
        // Members
        public string @code;
        public string @detail;

        // Constructor
        public Platform(
                string @code, 
                string @detail) : base(
                "@code" + "=" + @code+ ", " +
                "@detail" + "=" + @detail) {

            this.@code = @code;

            this.@detail = @detail;
        }
    }
    
    /// <summary>
    /// The customer's KMS returned an error. No platform code is assigned
    /// (upstream vendor failures are not `K9O_*` codes).
    /// </summary>
    
    public class UpstreamKms : ZkFfiUniffiException {
        // Members
        public string @detail;

        // Constructor
        public UpstreamKms(
                string @detail) : base(
                "@detail" + "=" + @detail) {

            this.@detail = @detail;
        }
    }
    
    /// <summary>
    /// The requested posture or oracle mode is below the project-declared
    /// policy floor (`K9O_CRYPTO_POSTURE_FLOOR_VIOLATION`).
    /// </summary>
    
    public class PostureViolation : ZkFfiUniffiException {
        // Members
        public string @code;
        public string @detail;
        public string @dimension;
        public string @requested;
        public string @declared;

        // Constructor
        public PostureViolation(
                string @code, 
                string @detail, 
                string @dimension, 
                string @requested, 
                string @declared) : base(
                "@code" + "=" + @code+ ", " +
                "@detail" + "=" + @detail+ ", " +
                "@dimension" + "=" + @dimension+ ", " +
                "@requested" + "=" + @requested+ ", " +
                "@declared" + "=" + @declared) {

            this.@code = @code;

            this.@detail = @detail;

            this.@dimension = @dimension;

            this.@requested = @requested;

            this.@declared = @declared;
        }
    }
    

    
}

class FfiConverterTypeZkFfiUniffiError : FfiConverterRustBuffer<ZkFfiUniffiException>, CallStatusErrorHandler<ZkFfiUniffiException> {
    public static FfiConverterTypeZkFfiUniffiError INSTANCE = new FfiConverterTypeZkFfiUniffiError();

    public override ZkFfiUniffiException Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new ZkFfiUniffiException.Platform(
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterString.INSTANCE.Read(stream));
            case 2:
                return new ZkFfiUniffiException.UpstreamKms(
                    FfiConverterString.INSTANCE.Read(stream));
            case 3:
                return new ZkFfiUniffiException.PostureViolation(
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterString.INSTANCE.Read(stream));
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeZkFfiUniffiError.Read()", value));
        }
    }

    public override int AllocationSize(ZkFfiUniffiException value) {
        switch (value) {

            case ZkFfiUniffiException.Platform variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@code)
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@detail);

            case ZkFfiUniffiException.UpstreamKms variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@detail);

            case ZkFfiUniffiException.PostureViolation variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@code)
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@detail)
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@dimension)
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@requested)
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@declared);
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeZkFfiUniffiError.AllocationSize()", value));
        }
    }

    public override void Write(ZkFfiUniffiException value, BigEndianStream stream) {
        switch (value) {
            case ZkFfiUniffiException.Platform variant_value:
                stream.WriteInt(1);
                FfiConverterString.INSTANCE.Write(variant_value.@code, stream);
                FfiConverterString.INSTANCE.Write(variant_value.@detail, stream);
                break;
            case ZkFfiUniffiException.UpstreamKms variant_value:
                stream.WriteInt(2);
                FfiConverterString.INSTANCE.Write(variant_value.@detail, stream);
                break;
            case ZkFfiUniffiException.PostureViolation variant_value:
                stream.WriteInt(3);
                FfiConverterString.INSTANCE.Write(variant_value.@code, stream);
                FfiConverterString.INSTANCE.Write(variant_value.@detail, stream);
                FfiConverterString.INSTANCE.Write(variant_value.@dimension, stream);
                FfiConverterString.INSTANCE.Write(variant_value.@requested, stream);
                FfiConverterString.INSTANCE.Write(variant_value.@declared, stream);
                break;
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeZkFfiUniffiError.Write()", value));
        }
    }
}




class FfiConverterOptionalString: FfiConverterRustBuffer<string?> {
    public static FfiConverterOptionalString INSTANCE = new FfiConverterOptionalString();

    public override string? Read(BigEndianStream stream) {
        if (stream.ReadByte() == 0) {
            return null;
        }
        return FfiConverterString.INSTANCE.Read(stream);
    }

    public override int AllocationSize(string? value) {
        if (value == null) {
            return 1;
        } else {
            return 1 + FfiConverterString.INSTANCE.AllocationSize((string)value);
        }
    }

    public override void Write(string? value, BigEndianStream stream) {
        if (value == null) {
            stream.WriteByte(0);
        } else {
            stream.WriteByte(1);
            FfiConverterString.INSTANCE.Write((string)value, stream);
        }
    }
}




